v=V(63,'Công việc cụ thể','help animals=giúp động vật|fix cars=sửa ô tô|sell things=bán hàng|make things=làm ra đồ vật|take pictures=chụp ảnh|catch fish=bắt cá','A photographer takes pictures.=Nhiếp ảnh gia chụp ảnh.|A fisherman catches fish.=Ngư dân bắt cá.')
P(64,'Nghề, công việc và nơi làm việc',v,'What does a salesclerk do?=Nhân viên bán hàng làm gì?|A salesclerk sells things.=Nhân viên bán hàng bán hàng hóa.|A mechanic fixes cars in a garage.=Thợ sửa xe sửa ô tô trong ga ra.|A salesclerk sells things in a store.=Nhân viên bán hàng bán hàng trong cửa hàng.',qa=[('What does a salesclerk do?','A salesclerk sells things.')])
P(65,'Trò chơi đoán nghề',s="I work in a store.=Mình làm việc trong cửa hàng.|I sell things.=Mình bán hàng.|What's my job?=Nghề của mình là gì?|You're a salesclerk!=Bạn là nhân viên bán hàng!|I wear a uniform.=Mình mặc đồng phục.|I drive a police car.=Mình lái xe cảnh sát.|You're a police officer!=Bạn là cảnh sát!")
P(66,'Đọc: nhiếp ảnh gia Maya','animal photographer=nhiếp ảnh gia động vật|outside=ở ngoài trời','Maya is an animal photographer.=Maya là nhiếp ảnh gia động vật.|She takes pictures of animals every day.=Cô ấy chụp ảnh động vật mỗi ngày.|She never takes pictures of people.=Cô ấy không bao giờ chụp ảnh người.|Be careful, Maya!=Hãy cẩn thận, Maya!',qa=[('What does Maya do?','She is an animal photographer.'),('Does she ever work outside?','Yes. She usually takes pictures outside.'),('Is she taking a picture of a tree?','No. She is taking a picture of a lion.')])
P(67,'Sở thích thể thao',s='Do you like sports?=Bạn có thích thể thao không?|Yes, I do.=Có.|Which sports do you like?=Bạn thích những môn thể thao nào?|I like football and soccer.=Mình thích bóng bầu dục Mỹ và bóng đá.|Which sport do you like more?=Bạn thích môn thể thao nào hơn?|I like soccer more.=Mình thích bóng đá hơn.',qa=[('Which sports do you like?','I like football and soccer.'),('Which sport do you like more?','I like soccer more.')])
P(68,'Các môn thể thao','football=bóng bầu dục Mỹ|baseball=bóng chày|basketball=bóng rổ|volleyball=bóng chuyền|track=điền kinh|tennis=quần vợt|soccer=bóng đá','Which do you like more, football or soccer?=Bạn thích bóng bầu dục Mỹ hay bóng đá hơn?|I like soccer more.=Mình thích bóng đá hơn.|What about you?=Còn bạn thì sao?')
v=V(69,'Trước đây và bây giờ; đặc điểm','small=nhỏ|big=to|light=nhẹ|heavy=nặng|weak=yếu|strong=khỏe|slow=chậm|fast=nhanh',"He was small. Now he's big.=Trước đây cậu ấy nhỏ. Bây giờ cậu ấy to.|Is he fast?=Cậu ấy có nhanh không?|Yes, he is.=Có.")
P(70,'Hỏi đặc điểm trước đây và bây giờ',v,"Is he big?=Cậu ấy có to không?|Was he small?=Trước đây cậu ấy có nhỏ không?|Yes, he was.=Có.|They were slow.=Trước đây họ chậm.|Now they're fast.=Bây giờ họ nhanh.")
v=V(71,'Vận động viên và so sánh','a swimmer=một vận động viên bơi|a baseball player=một cầu thủ bóng chày|a volleyball player=một cầu thủ bóng chuyền|a runner=một vận động viên chạy|a gymnast=một vận động viên thể dục dụng cụ|a football player=một cầu thủ bóng bầu dục Mỹ','The swimmer is bigger than the gymnast.=Vận động viên bơi to hơn vận động viên thể dục dụng cụ.|The gymnast is smaller than the swimmer.=Vận động viên thể dục dụng cụ nhỏ hơn vận động viên bơi.|Who is faster?=Ai nhanh hơn?|The runner is faster.=Vận động viên chạy nhanh hơn.')
P(72,'So sánh đặc điểm','stronger=khỏe hơn|weaker=yếu hơn|heavier=nặng hơn|lighter=nhẹ hơn|bigger=to hơn|smaller=nhỏ hơn',"Who is stronger?=Ai khỏe hơn?|The volleyball player is stronger.=Cầu thủ bóng chuyền khỏe hơn.|Is the swimmer stronger?=Vận động viên bơi có khỏe hơn không?|No, he isn't.=Không.")
P(73,'So sánh hai đồ vật','small=nhỏ|big=to|short=thấp|tall=cao|light=nhẹ|heavy=nặng|slow=chậm|fast=nhanh|young=trẻ|old=già|strong=khỏe|weak=yếu','The car is smaller than the truck.=Ô tô nhỏ hơn xe tải.|The truck is bigger than the car.=Xe tải to hơn ô tô.|Which one is bigger, the car or the truck?=Cái nào to hơn, ô tô hay xe tải?',qa=[('Which one is bigger, the car or the truck?','The truck is bigger than the car.')])
P(74,'Đọc: vận động viên trượt tuyết Jim','skier=vận động viên trượt tuyết|skiing=trượt tuyết|jumping=nhảy','Jim is a skier.=Jim là vận động viên trượt tuyết.|He likes skiing and jumping.=Cậu ấy thích trượt tuyết và nhảy.|He was short and weak.=Trước đây cậu ấy thấp và yếu.|Now he is tall and strong.=Bây giờ cậu ấy cao và khỏe.',qa=[('What does Jim like to do?','He likes skiing and jumping.'),('Is he weak?','No. He is strong now.'),('Is Jim going to be in the Winter Games?','Yes, he is.')])
P(75,'Review 7–8','a photographer=một nhiếp ảnh gia|a fisherman=một ngư dân|strong=khỏe|fast=nhanh',"What's his job?=Nghề của anh ấy là gì?|What does a fisherman do?=Ngư dân làm gì?|Who is faster?=Ai nhanh hơn?",note='Ôn qua hình Unit 7–8; không suy đoán đáp án nghe gốc.')
P(76,'Read: Melissa','tour guide=hướng dẫn viên du lịch|tourists=những khách du lịch','My name is Melissa.=Tên mình là Melissa.|I live in Canada.=Mình sống ở Canada.|My mother is a tour guide.=Mẹ mình là hướng dẫn viên du lịch.|She helps tourists.=Mẹ mình giúp khách du lịch.|Sometimes I help my mother.=Thỉnh thoảng mình giúp mẹ.|I like to help tourists, too.=Mình cũng thích giúp khách du lịch.',qa=[('Where does Melissa live?','She lives in Canada.'),('What does her mother do?','She is a tour guide.')])

